import {configureLessons} from './curriculum.js';
import {Chess} from './vendor/chess.js';
export const themes={
 fork:{name:'Forks',phase:'Middlegame',text:'One piece attacks two targets at once. The opponent can often save only one.',cue:'Look for a check that also attacks a queen, rook or loose piece.',mistake:'A fork is useful only if your attacking piece cannot simply be captured.'},
 pin:{name:'Pins',phase:'Middlegame',text:'A piece is pinned when moving it exposes something more valuable behind it.',cue:'Scan straight lines toward the king or queen.',mistake:'A piece pinned to its king cannot expose that king; a piece pinned to a queen may still move.'},
 skewer:{name:'Skewers',phase:'Middlegame',text:'Attack the valuable front piece so it moves and leaves the piece behind exposed.',cue:'Find two enemy pieces on the same rank, file or diagonal.',mistake:'Check whether the rear piece can be defended after the front piece moves.'},
 discoveredAttack:{name:'Discovered attacks',phase:'Middlegame',text:'Move one piece out of the way to uncover an attack from another.',cue:'Look for a bishop or rook whose line is blocked by your own piece.',mistake:'The moving piece still needs a safe or forcing destination.'},
 doubleCheck:{name:'Double check',phase:'Middlegame',text:'Two pieces check the king at the same time. The defender must move the king.',cue:'Move a piece with check while uncovering a second checking line.',mistake:'Both attacks must really reach the king after your move.'},
 backRankMate:{name:'Back-rank mate',phase:'Middlegame',text:'A rook or queen mates a king trapped behind its own pawns.',cue:'Find a clear back rank and a king with no escape square.',mistake:'Check for a defender that can capture your attacking piece or block the file.'},
 mateIn1:{name:'Mate in one',phase:'Middlegame',text:'Find a move that checks the king and leaves no legal escape, capture or block.',cue:'Check every checking move; test all defensive replies.',mistake:'Check is not checkmate if the king can escape or the attack can be stopped.'},
 mateIn2:{name:'Mate in two',phase:'Middlegame',text:'Your first move forces a reply, then your second move delivers checkmate.',cue:'Find a forcing move that closes escape squares.',mistake:'Your line must work against the defender’s replies, not just a convenient one.'},
 mateIn3:{name:'Mate in three',phase:'Middlegame',text:'A sequence of three attacking moves ends in mate, with defensive replies between them.',cue:'Count your own moves; visualize how each move changes the king’s space.',mistake:'Do not stop calculation after the first check.'},
 sacrifice:{name:'Sacrifices',phase:'Middlegame',text:'Give material for a concrete benefit: an attack, promotion, forced mate or greater material.',cue:'Look for a forcing continuation after the opponent accepts.',mistake:'A tempting sacrifice still needs a calculated continuation.'},
 deflection:{name:'Deflection',phase:'Middlegame',text:'Lure a defender away from the piece or square it protects.',cue:'Identify a defender with two important jobs.',mistake:'Make sure the opponent cannot decline the distraction safely.'},
 attraction:{name:'Attraction',phase:'Middlegame',text:'Draw an enemy piece onto a square where a tactic becomes possible.',cue:'Look for a capture that pulls the king into a fork or mating net.',mistake:'Check that the following tactic really works after the lure.'},
 clearance:{name:'Clearance',phase:'Middlegame',text:'Vacate a square or line so a different piece can use it.',cue:'Ask which friendly piece is obstructing a stronger attack.',mistake:'A clearance move must not give the opponent time to stop your plan.'},
 intermezzo:{name:'In-between moves',phase:'Middlegame',text:'Insert a forcing move before the expected recapture.',cue:'Before taking back, look for checks and direct threats.',mistake:'An in-between move can fail if your hanging piece is too valuable.'},
 hangingPiece:{name:'Loose pieces',phase:'Middlegame',text:'An undefended piece can become the target of a direct capture or combination.',cue:'Inventory what is attacked and what is defended.',mistake:'An apparently free piece may be protected by a tactical threat.'},
 defensiveMove:{name:'Defensive saves',phase:'Middlegame',text:'Meet the opponent’s threat while keeping your position together.',cue:'Ask what the opponent would play if you passed your turn.',mistake:'Do not assume every training position demands an attacking move.'},
 quietMove:{name:'Quiet moves',phase:'Middlegame',text:'A move without check or capture can create an unavoidable threat.',cue:'Find the square that improves coordination or removes an escape.',mistake:'A quiet move needs a threat strong enough to survive the opponent’s reply.'},
 pawnEndgame:{name:'Pawn endings',phase:'Endgame',text:'King activity, promotion squares and the race between pawns decide many pawn endings.',cue:'Count moves to promotion and include king moves and checks.',mistake:'A pawn race can change when promotion gives check.'},
 rookEndgame:{name:'Rook endings',phase:'Endgame',text:'Rooks thrive on activity. Cut off the king and use checks or passed pawns to create chances.',cue:'Look for active checks, a cutoff and the square behind a passed pawn.',mistake:'Do not abandon an active rook for a passive defense without calculating.'},
 bishopEndgame:{name:'Bishop endings',phase:'Endgame',text:'Diagonals, pawn colors and king access determine a bishop’s usefulness.',cue:'Compare the bishop’s color with important pawn and promotion squares.',mistake:'A bishop cannot control a square of the opposite color.'},
 knightEndgame:{name:'Knight endings',phase:'Endgame',text:'Knights use forks and blockades, but need time to reach distant pawns.',cue:'Find knight routes that attack a pawn with tempo.',mistake:'A knight cannot lose a tempo without changing its square color.'},
 queenEndgame:{name:'Queen endings',phase:'Endgame',text:'Checks, king safety and promotion threats matter even with few pieces remaining.',cue:'Inspect forcing checks before committing to a pawn race.',mistake:'An exposed king can allow perpetual check despite extra material.'},
 promotion:{name:'Promotion',phase:'Endgame',text:'A pawn on the final rank becomes a queen, rook, bishop or knight.',cue:'Look for a forcing path to the eighth rank.',mistake:'Always consider underpromotion when a queen would cause stalemate or miss a fork.'},
 underPromotion:{name:'Underpromotion',phase:'Endgame',text:'Choose a rook, bishop or knight instead of a queen when it changes the result.',cue:'Check for a knight fork or a stalemate after queen promotion.',mistake:'The most powerful piece is not always the right piece.'},
 zugzwang:{name:'Zugzwang',phase:'Endgame',text:'The obligation to move can make every legal option worse.',cue:'Compare the same position with each side to move.',mistake:'Avoid assuming that moving closer always improves a king ending.'},
 kingsideAttack:{name:'King attacks',phase:'Middlegame',text:'Coordinate pieces against the king, removing defenders and controlling escape squares.',cue:'Count attackers, defenders and forcing moves near the king.',mistake:'An attack can run out if your pieces do not join it in time.'}
};
export function label(tag){return themes[tag]?.name||tag.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase())}
export function primaryTag(p){const priority=['backRankMate','fork','pin','skewer','discoveredAttack','doubleCheck','deflection','attraction','underPromotion','promotion','zugzwang','intermezzo','sacrifice','defensiveMove','quietMove','pawnEndgame','rookEndgame','bishopEndgame','knightEndgame','queenEndgame','mateIn1','mateIn2','mateIn3','hangingPiece','kingsideAttack','clearance'];return priority.find(t=>p.themes.includes(t))||'calculation'}
const sparse=(pieces,turn='w',rights='-')=>{let rows=[];for(let r=8;r>=1;r--){let row='',n=0;for(let f=0;f<8;f++){const p=pieces[String.fromCharCode(97+f)+r];if(p){if(n){row+=n;n=0}row+=p}else n++}if(n)row+=n;rows.push(row)}return rows.join('/')+` ${turn} ${rights} - 0 30`};
const base={a1:'K',h8:'k'};
