for(const l of lessons){if(l.fen==='start')l.fen=new Chess().fen();l.positionKind ||= 'composed-exercise';}
configureLessons(lessons,sparse);
export const phaseCopy={opening:'Opening tactics',middlegame:'Middlegame patterns',endgame:'Endgame techniques'};
export function difficulty(rating){return rating<1200?'Starter':rating<1700?'Building':rating<2100?'Challenging':'Advanced'}
